/**
 * Certificate Service
 *
 * Manages X.509 self-signed certificates for doctors.
 * Used for PAdES digital signature of prescription PDFs.
 *
 * Phase 2: Self-signed certificates generated by the platform.
 * Phase 3: Will integrate with external AC providers (Lakaut, Encode, AFIP).
 *
 * NOTE: node-forge is dynamically imported to avoid bundling into
 * the Cloudflare Workers runtime (uses Node.js createRequire).
 */
import type { SupabaseClient } from '@supabase/supabase-js';
import { logger } from '@autamedica/shared';

export interface CertificateInfo {
  id: string;
  doctorId: string;
  acProvider: string;
  certFingerprint: string;
  certSubject: string;
  certValidFrom: string;
  certValidUntil: string;
  certStatus: string;
  signatureMethod: string;
}

interface DoctorIdentity {
  doctorId: string;
  fullName: string;
  licenseNumber: string;
  jurisdiction?: string;
  refepsId?: string;
}

/**
 * Generates a self-signed X.509 certificate and PKCS#12 bundle for a doctor.
 * Returns the PEM certificate (public) and the P12 buffer (private, password-protected).
 */
export async function generateSelfSignedCertificate(identity: DoctorIdentity, password: string): Promise<{
  certPem: string;
  p12Buffer: Buffer;
  fingerprint: string;
  subject: string;
  validFrom: Date;
  validUntil: Date;
}> {
  const forge = (await import('node-forge')).default;
  const keys = forge.pki.rsa.generateKeyPair(2048);
  const cert = forge.pki.createCertificate();

  cert.publicKey = keys.publicKey;
  cert.serialNumber = Date.now().toString(16);

  const now = new Date();
  const validUntil = new Date(now);
  validUntil.setFullYear(validUntil.getFullYear() + 2);

  cert.validity.notBefore = now;
  cert.validity.notAfter = validUntil;

  const subjectAttrs = [
    { name: 'commonName', value: identity.fullName },
    { name: 'organizationName', value: 'AutaMedica' },
    { name: 'organizationalUnitName', value: 'Prescripciones Electrónicas' },
    { name: 'countryName', value: 'AR' },
    { shortName: 'serialNumber', value: `MP-${identity.licenseNumber}` },
  ];

  if (identity.jurisdiction) {
    subjectAttrs.push({ name: 'stateOrProvinceName', value: identity.jurisdiction });
  }

  cert.setSubject(subjectAttrs);
  cert.setIssuer([
    { name: 'commonName', value: 'AutaMedica Platform CA' },
    { name: 'organizationName', value: 'AutaMedica' },
    { name: 'countryName', value: 'AR' },
  ]);

  cert.setExtensions([
    { name: 'basicConstraints', cA: false },
    { name: 'keyUsage', digitalSignature: true, nonRepudiation: true },
    {
      name: 'extKeyUsage',
      serverAuth: false,
      clientAuth: false,
      codeSigning: false,
      emailProtection: true,
    },
    {
      name: 'subjectAltName',
      altNames: [
        { type: 6, value: `urn:autamedica:doctor:${identity.doctorId}` },
      ],
    },
  ]);

  cert.sign(keys.privateKey, forge.md.sha256.create());

  const certPem = forge.pki.certificateToPem(cert);
  const fingerprint = forge.md.sha256
    .create()
    .update(forge.asn1.toDer(forge.pki.certificateToAsn1(cert)).getBytes())
    .digest()
    .toHex();

  const subject = subjectAttrs
    .map((a) => `${a.shortName ?? a.name}=${a.value}`)
    .join(', ');

  // Create PKCS#12
  const p12Asn1 = forge.pkcs12.toPkcs12Asn1(keys.privateKey, [cert], password, {
    algorithm: '3des',
    friendlyName: `AutaMedica-${identity.licenseNumber}`,
  });
  const p12Der = forge.asn1.toDer(p12Asn1).getBytes();
  const p12Buffer = Buffer.from(p12Der, 'binary');

  return { certPem, p12Buffer, fingerprint, subject, validFrom: now, validUntil };
}

/**
 * Provisions a self-signed certificate for a doctor.
 * Stores the public cert info in `signature_certificates` and
 * the PKCS#12 bundle in Supabase Storage (encrypted).
 */
export async function provisionDoctorCertificate(
  supabase: SupabaseClient,
  identity: DoctorIdentity,
): Promise<CertificateInfo> {
  // Generate a strong random password for the P12
  const forge = (await import('node-forge')).default;
  const password = forge.util.bytesToHex(forge.random.getBytesSync(16));

  const { certPem, p12Buffer, fingerprint, subject, validFrom, validUntil } =
    await generateSelfSignedCertificate(identity, password);

  // Store P12 in Supabase Storage (encrypted at rest)
  const p12Path = `certificates/${identity.doctorId}/${fingerprint}.p12`;
  const { error: uploadErr } = await supabase.storage
    .from('medical-documents')
    .upload(p12Path, p12Buffer, {
      contentType: 'application/x-pkcs12',
      upsert: true,
    });

  if (uploadErr) {
    logger.error('[certificate] P12 upload failed', uploadErr);
    throw new Error('Failed to store certificate');
  }

  // Store password in a separate secret file (only accessible via service_role)
  const secretPath = `certificates/${identity.doctorId}/${fingerprint}.secret`;
  const { error: secretErr } = await supabase.storage
    .from('medical-documents')
    .upload(secretPath, Buffer.from(password), {
      contentType: 'text/plain',
      upsert: true,
    });

  if (secretErr) {
    logger.error('[certificate] Secret upload failed', secretErr);
    throw new Error('Failed to store certificate secret');
  }

  // Store PEM (public) for easy retrieval
  const pemPath = `certificates/${identity.doctorId}/${fingerprint}.pem`;
  await supabase.storage
    .from('medical-documents')
    .upload(pemPath, Buffer.from(certPem), {
      contentType: 'application/x-pem-file',
      upsert: true,
    });

  // Revoke any existing active certificates for this doctor
  await supabase
    .from('signature_certificates')
    .update({ cert_status: 'revoked' })
    .eq('doctor_id', identity.doctorId)
    .eq('cert_status', 'active');

  // Insert new certificate record
  const { data: certRecord, error: insertErr } = await supabase
    .from('signature_certificates')
    .insert({
      doctor_id: identity.doctorId,
      ac_provider: 'self_signed',
      cert_fingerprint: fingerprint,
      cert_subject: subject,
      cert_valid_from: validFrom.toISOString(),
      cert_valid_until: validUntil.toISOString(),
      cert_status: 'active',
      signature_method: 'electronic_simple',
    })
    .select('id')
    .single();

  if (insertErr) {
    logger.error('[certificate] DB insert failed', insertErr);
    throw new Error('Failed to register certificate');
  }

  logger.info('[certificate] Provisioned', {
    doctorId: identity.doctorId,
    fingerprint,
    validUntil: validUntil.toISOString(),
  });

  return {
    id: certRecord.id,
    doctorId: identity.doctorId,
    acProvider: 'self_signed',
    certFingerprint: fingerprint,
    certSubject: subject,
    certValidFrom: validFrom.toISOString(),
    certValidUntil: validUntil.toISOString(),
    certStatus: 'active',
    signatureMethod: 'electronic_simple',
  };
}

/**
 * Gets the active certificate for a doctor, or null if none exists.
 */
export async function getActiveCertificate(
  supabase: SupabaseClient,
  doctorId: string,
): Promise<CertificateInfo | null> {
  const { data } = await supabase
    .from('signature_certificates')
    .select('*')
    .eq('doctor_id', doctorId)
    .eq('cert_status', 'active')
    .order('created_at', { ascending: false })
    .limit(1)
    .single();

  if (!data) return null;

  return {
    id: data.id,
    doctorId: data.doctor_id,
    acProvider: data.ac_provider,
    certFingerprint: data.cert_fingerprint,
    certSubject: data.cert_subject,
    certValidFrom: data.cert_valid_from,
    certValidUntil: data.cert_valid_until,
    certStatus: data.cert_status,
    signatureMethod: data.signature_method,
  };
}

/**
 * Loads the PKCS#12 bundle and password for signing operations.
 * Only callable with a service_role client.
 */
export async function loadSigningCredentials(
  supabase: SupabaseClient,
  doctorId: string,
  fingerprint: string,
): Promise<{ p12Buffer: Buffer; password: string }> {
  const p12Path = `certificates/${doctorId}/${fingerprint}.p12`;
  const secretPath = `certificates/${doctorId}/${fingerprint}.secret`;

  const { data: p12Data, error: p12Err } = await supabase.storage
    .from('medical-documents')
    .download(p12Path);

  if (p12Err || !p12Data) {
    throw new Error(`Failed to load P12: ${p12Err?.message}`);
  }

  const { data: secretData, error: secretErr } = await supabase.storage
    .from('medical-documents')
    .download(secretPath);

  if (secretErr || !secretData) {
    throw new Error(`Failed to load secret: ${secretErr?.message}`);
  }

  const p12Buffer = Buffer.from(await p12Data.arrayBuffer());
  const password = await secretData.text();

  return { p12Buffer, password };
}
